	sui	78h	; A := A−78h (0..17h) — дельта строки
	add	d
	mov	d,a	; D += дельта (строка)
	mov	a,m	; следующий байт — дельта столбца
	add	e
	mov	e,a	; E += [HL] (столбец)
	inx	h	; пропустить операнд
